import{_ as t,o,c as a,a5 as d}from"./chunks/framework.Cooo9kuv.js";const b=JSON.parse('{"title":"静态管理中心 — Z-BlogPHP 伪静态插件","description":"","frontmatter":{"标题":"ZBlogPHP 伪静态插件 — 静态管理中心","日期":"2026-07-11T00:00:00.000Z","修改日期":"2026-07-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["zblog主题插件"],"标签":["301重定向","Apache伪静态","Nginx伪静态","SEO优化","URL重写","Z-BlogPHP伪静态","ZBlog伪静态插件","伪静态规则配置","搜索引擎优化","搜索引擎收录","搜索排名提升","网站URL静态化"]},"headers":[],"relativePath":"md/zblog主题插件/ZBlogPHP 伪静态插件 — 静态管理中心.md","filePath":"md/zblog主题插件/ZBlogPHP 伪静态插件 — 静态管理中心.md"}'),r={name:"md/zblog主题插件/ZBlogPHP 伪静态插件 — 静态管理中心.md"};function c(h,e,l,i,n,s){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="静态管理中心-—-z-blogphp-伪静态插件" tabindex="-1">静态管理中心 — Z-BlogPHP 伪静态插件 <a class="header-anchor" href="#静态管理中心-—-z-blogphp-伪静态插件" aria-label="Permalink to &quot;静态管理中心 — Z-BlogPHP 伪静态插件&quot;">​</a></h1><blockquote><p>将 Z-BlogPHP 文章、页面、分类、标签、作者、日期归档等页面的动态 URL 转换为伪静态格式，提升搜索引擎友好度。内置 301 自动重定向，兼容 Apache / Nginx / IIS / Lighttpd 主流服务器。</p></blockquote><p><strong>版本</strong>：v3.10<br><strong>适配</strong>：Z-BlogPHP 1.7.0+<br><strong>PHP</strong>：≥ 7.2<br><strong>作者</strong>：softbangong<br><strong>授权</strong>：不限制网站数量，下载安装后永久免费使用</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image.png" alt="zblog静态管理中心"></p><h2 id="插件简介" tabindex="-1">插件简介 <a class="header-anchor" href="#插件简介" aria-label="Permalink to &quot;插件简介&quot;">​</a></h2><p>本插件用于管理 Z-BlogPHP 网站的 URL 伪静态规则，将原本带问号参数（如 <code>/?id=123</code>）的动态链接，重写为搜索引擎和访客更容易识别、记忆的静态格式链接（如 <code>/post/123.html</code>）。</p><p>插件在后台提供了集中化的配置管理界面，支持三种 URL 模式一键切换、每种页面类型单独配置规则、实时预览最终 URL 效果，并且可根据中文站或英文站给出不同的 SEO 评分作为参考，帮助您快速选择最优方案。</p><p>同时，插件在 PHP 层面自动实现了 301 永久重定向：当访客或搜索引擎通过旧的动态链接访问时，会自动跳转到对应的新静态地址，防止出现重复内容，利于 SEO 收录和排名。</p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><h3 id="三种-url-模式-一键切换" tabindex="-1">三种 URL 模式，一键切换 <a class="header-anchor" href="#三种-url-模式-一键切换" aria-label="Permalink to &quot;三种 URL 模式，一键切换&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th>URL 示例</th><th>说明</th></tr></thead><tbody><tr><td>动态模式</td><td><code>/?id=123</code></td><td>原始动态链接，无需服务器 Rewrite 组件</td></tr><tr><td>index.php 式伪静态</td><td><code>/index.php/post/123.html</code></td><td>Apache / IIS 下无需额外配置 Rewrite 规则即可使用</td></tr><tr><td>index.php 式伪静态</td><td><code>/index.php/post/123.html</code></td><td>Apache / IIS 下无需额外配置 Rewrite 规则即可使用</td></tr></tbody></table><p>您可以随时在三种模式之间切换。切换到动态模式时，插件会自动清除之前生成的 <code>.htaccess</code> 规则，保留您自行添加的自定义内容。</p><h3 id="智能-seo-评分" tabindex="-1">智能 SEO 评分 <a class="header-anchor" href="#智能-seo-评分" aria-label="Permalink to &quot;智能 SEO 评分&quot;">​</a></h3><p>每种 URL 规则模板都会显示 1 到 5 星的 SEO 评分，您可以直观地比较不同规则的优劣：</p><p>— <strong>中文站</strong>优先推荐纯数字 ID 的 URL（如 <code>/post/123.html</code>），对百度等国内搜索引擎更友好，URL 简洁稳定；<br> — <strong>英文站</strong>优先推荐含关键词别名的 URL（如 <code>/post/hello-world.html</code>），对 Google 等搜索引擎更友好，URL 语义丰富；<br> — 插件后台提供「中文站 / 英文站」一键切换按钮，切换后所有评分和推荐规则会即时更新，同时自动为您重选当前语言下的最优预设。</p><h3 id="_301-自动重定向" tabindex="-1">301 自动重定向 <a class="header-anchor" href="#_301-自动重定向" aria-label="Permalink to &quot;301 自动重定向&quot;">​</a></h3><p>插件在 PHP 层自动实现了 301 永久重定向功能，启用后无需任何额外配置即可生效：</p><p>— 旧动态链接（如 <code>/?id=123</code>）被访问时，自动 301 跳转到您配置的新静态地址（如 <code>/post/123.html</code>）；<br> — 自动识别旧 <code>/index.php/post/123.html</code> 等格式的链接并跳转到当前配置的静态 URL；<br> — 内置循环检测机制：如果当前请求的 URL 已经是目标地址，则跳过跳转，不会产生无限重定向；<br> — 自动排除管理后台路径（<code>/zb_system/</code>、<code>/zb_install/</code>、<code>/zb_users/</code>），确保后台功能不受影响。</p><p>此外，Apache 用户还可以在「ReWrite规则」页面追加服务器层的 301 规则，让重定向在 PHP 运行之前由 Apache 完成，进一步提升性能。</p><h3 id="多服务器-rewrite-规则生成" tabindex="-1">多服务器 Rewrite 规则生成 <a class="header-anchor" href="#多服务器-rewrite-规则生成" aria-label="Permalink to &quot;多服务器 Rewrite 规则生成&quot;">​</a></h3><p>插件支持主流 Web 服务器的规则配置，可在后台自动生成对应格式的配置文件：</p><p>— <strong>Apache .htaccess</strong>：自动生成三个独立区块 —— Rewrite 重写规则、301 重定向规则、旧链接跳转规则。每个区块可单独生成、更新或清除，不覆盖您已有的自定义规则；<br> — <strong>IIS 7+ web.config</strong>：适用于安装了微软官方 URL Rewrite Module 的 IIS 7 及以上版本；<br> — <strong>IIS 6 httpd.ini</strong>：适用于安装了 ISAPI Rewrite 组件的 IIS 6；<br> — <strong>Nginx 配置</strong>：生成可直接放入 server 或 location 节点的配置规则；<br> — <strong>Lighttpd 配置</strong>：生成 lighttpd.conf 格式的伪静态规则。</p><p>所有规则均支持一键生成配置文件到网站根目录，也支持手动复制粘贴。</p><h3 id="实时-url-预览" tabindex="-1">实时 URL 预览 <a class="header-anchor" href="#实时-url-预览" aria-label="Permalink to &quot;实时 URL 预览&quot;">​</a></h3><p>在配置页面修改任何 URL 规则或切换模式时，页面底部会即时显示该规则对应的最终 URL 效果。例如选择文章规则为 <code>{%host%}post/{%id%}.html</code> 时，预览区会立即显示 <code>https://www.example.com/post/123.html</code>，所见即所得，方便您确认规则是否正确。</p><h3 id="页面类型全覆盖" tabindex="-1">页面类型全覆盖 <a class="header-anchor" href="#页面类型全覆盖" aria-label="Permalink to &quot;页面类型全覆盖&quot;">​</a></h3><p>插件支持 Z-BlogPHP 以下页面类型的 URL 规则配置，每种类型都有独立的输入框和预设选项：</p><table tabindex="0"><thead><tr><th>类型</th><th>可用变量</th></tr></thead><tbody><tr><td>文章页</td><td><code>{%host%}</code> <code>{%id%}</code> <code>{%alias%}</code> <code>{%year%}</code> <code>{%month%}</code></td></tr><tr><td>页面</td><td><code>{%host%}</code> <code>{%id%}</code> <code>{%alias%}</code></td></tr><tr><td>首页分页</td><td><code>{%host%}</code> <code>{%page%}</code></td></tr><tr><td>分类页</td><td><code>{%host%}</code> <code>{%id%}</code> <code>{%alias%}</code> <code>{%page%}</code></td></tr><tr><td>标签页</td><td><code>{%host%}</code> <code>{%id%}</code> <code>{%alias%}</code> <code>{%page%}</code></td></tr><tr><td>日期归档</td><td><code>{%host%}</code> <code>{%date%}</code> <code>{%page%}</code></td></tr><tr><td>日期归档</td><td><code>{%host%}</code> <code>{%date%}</code> <code>{%page%}</code></td></tr></tbody></table><h3 id="管理后台安全保护" tabindex="-1">管理后台安全保护 <a class="header-anchor" href="#管理后台安全保护" aria-label="Permalink to &quot;管理后台安全保护&quot;">​</a></h3><p>— 自动排除 Z-BlogPHP 管理后台路径（<code>/zb_system/</code>、<code>/zb_install/</code>、<code>/zb_users/</code>），Rewrite 规则不会影响后台登录、设置、应用中心等页面的正常访问；<br> — 切换回动态模式时，自动清除插件生成的 <code>.htaccess</code> 相关规则区块，保留您自行添加的自定义内容。</p><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><h3 id="第一步-安装插件" tabindex="-1">第一步：安装插件 <a class="header-anchor" href="#第一步-安装插件" aria-label="Permalink to &quot;第一步：安装插件&quot;">​</a></h3><p>将 <code>wjt_jingtai</code> 文件夹上传至网站 <code>zb_users/plugin/</code> 目录，进入 Z-BlogPHP 后台「插件管理」页面，找到「静态管理中心」并点击启用。</p><h3 id="第二步-配置-url-规则" tabindex="-1">第二步：配置 URL 规则 <a class="header-anchor" href="#第二步-配置-url-规则" aria-label="Permalink to &quot;第二步：配置 URL 规则&quot;">​</a></h3><p>进入后台「插件管理 → 静态管理中心 → 配置页面」：</p><p>— 选择静态化模式：页面顶部提供「动态模式」「伪静态模式」「index.php 式伪静态」三个选项，点击即可切换；<br> — 为每种页面类型选择或自定义 URL 规则：每种类型都有一个文本输入框和一组预设选项（如文章页提供 6 种预设规则），点击预设即可自动填入；<br> — 每条预设规则右侧显示 SEO 星级评分（1-5 星）和对应的效果预览 URL，帮助您快速判断；<br> — 页面底部实时显示当前规则的预览 URL，确认无误后点击提交。</p><p>如果您不确定如何选择，推荐点击「一键伪静态」快捷卡片，插件会根据当前站点语言（中文站 / 英文站）自动为每种页面类型选出评分最高的规则，保存确认后自动跳转到规则生成页面。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/%E5%90%8E%E5%8F%B0%E9%A1%B5%E9%9D%A2%E6%88%AA%E5%9B%BE1-scaled.png" alt="zblog静态管理中心"></p><h3 id="第三步-生成-rewrite-规则-纯伪静态模式" tabindex="-1">第三步：生成 Rewrite 规则（纯伪静态模式） <a class="header-anchor" href="#第三步-生成-rewrite-规则-纯伪静态模式" aria-label="Permalink to &quot;第三步：生成 Rewrite 规则（纯伪静态模式）&quot;">​</a></h3><p>如果您选择了纯伪静态模式，需要生成对应的服务器规则文件。进入「静态管理中心 → ReWrite规则」页面：</p><p>— 页面顶部会根据您的服务器类型自动选中对应的 Tab（Apache / IIS / Nginx / Lighttpd）；<br> — 查看自动生成的规则内容，确认无误后点击「创建 / 更新」按钮一键生成配置文件；<br> — Apache 用户还可以分别追加「301 重定向规则」和「旧链接跳转规则」，两个规则区块独立管理，互不干扰。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/%E5%90%8E%E5%8F%B0%E9%A1%B5%E9%9D%A2%E6%88%AA%E5%9B%BE2.png" alt="zblog静态管理中心"></p><h3 id="第四步-验证生效" tabindex="-1">第四步：验证生效 <a class="header-anchor" href="#第四步-验证生效" aria-label="Permalink to &quot;第四步：验证生效&quot;">​</a></h3><p>— 访问网站前台任意文章或分类页面，检查浏览器地址栏 URL 是否已变为静态格式；<br> — 用旧的动态链接（如 <code>/?id=123</code>）测试访问，确认是否自动 301 跳转到新的静态地址；<br> — 进入后台配置页面，状态栏会实时显示当前模式和规则文件状态。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>— 本插件实现的是伪静态（URL 重写），并非生成纯静态 HTML 文件，页面数据仍然由 Z-BlogPHP 动态输出；<br> — 纯伪静态模式需要主机开启 Rewrite 模块。Apache 需要 <code>mod_rewrite</code>，IIS 7+ 需要安装 URL Rewrite Module（微软官方免费组件），IIS 6 需要 ISAPI Rewrite 组件；<br> — index.php 式伪静态不需要服务器 Rewrite 支持，Apache 和 IIS 用户可以直接使用，适合虚拟主机等无法自主配置 Rewrite 的环境；<br> — 网站安装在子目录时，生成的 Rewrite 规则可能需要手动微调路径前缀；<br> — 切换模式后，如果前台页面仍显示旧的 URL 格式，建议清除浏览器缓存后重新测试。</p><h2 id="反馈与支持" tabindex="-1">反馈与支持 <a class="header-anchor" href="#反馈与支持" aria-label="Permalink to &quot;反馈与支持&quot;">​</a></h2><p>— 作者：softbangong<br> — 作者网站：softbangong.top<br> — 作者网站：softbangong.com<br> — 邮箱：<a href="mailto:yunjuliangpin@163.com" target="_blank" rel="noreferrer">yunjuliangpin@163.com</a></p><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><h3 id="v3-10-2026-06-28" tabindex="-1">v3.10（2026-06-28） <a class="header-anchor" href="#v3-10-2026-06-28" aria-label="Permalink to &quot;v3.10（2026-06-28）&quot;">​</a></h3><p>— 新增中文站 / 英文站智能 SEO 评分体系，根据站点语言自动推荐最优 URL 规则；<br> — 新增「一键伪静态」快捷卡片，点击后自动选中所有页面类型的最优规则，确认后保存并跳转规则生成页；<br> — 新增旧 <code>/index.php/xxx</code> 格式链接的自动识别与 301 跳转；<br> — 新增管理后台路径自动排除机制（<code>/zb_system/</code>、<code>/zb_install/</code>、<code>/zb_users/</code>），防止 Rewrite 规则影响后台功能；<br> — 优化 301 重定向的循环检测逻辑，避免极端情况下的无限跳转；<br> — Apache .htaccess 的 301 规则支持自动生成，当 URL 模板包含 <code>{%alias%}</code> 时自动回退到 <code>index.php</code> 中转方案；<br> — 切换回动态模式时自动清理插件生成的 <code>.htaccess</code> 规则区块，保留用户自定义内容。</p><h3 id="v3-00-2026-06-01" tabindex="-1">v3.00（2026-06-01） <a class="header-anchor" href="#v3-00-2026-06-01" aria-label="Permalink to &quot;v3.00（2026-06-01）&quot;">​</a></h3><p>— 新增 PHP 层 301 自动重定向，无需服务器规则即可实现旧链接跳转；<br> — 新增 Apache .htaccess 的 301 重定向规则和旧链接跳转规则生成；<br> — 新增实时 URL 预览功能，修改规则即时显示最终效果；<br> — 新增 Nginx 和 Lighttpd 服务器规则支持；<br> — 后台配置界面全面重构，操作更直观。</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2950.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2950.html</a></p>',55)])])}const g=t(r,[["render",c]]);export{b as __pageData,g as default};
